15.2 Describe the demographic resource
demog_ptx_dictionary_field_described_list &lt;- {
  demog_description_chr &lt;- c(
    uid = "De-identified record identifier",
    age_in_months = "Age in months at interview",
    gender = "Gender",
    village_id = "Approved non-identifying village key",
    rururb = "Village rural/urban classification"
  )
  demog_schema_list &lt;- frictionless::create_schema(
    demog_clean_df
  )
  demog_field_name_chr &lt;- vapply(
    demog_schema_list$fields,
    `[[`,
    character(1),
    "name"
  )
  if (!setequal(names(demog_description_chr), demog_field_name_chr)) {
    stop("Demographic field descriptions do not match the curated columns.")
  }
  demog_schema_list$fields &lt;- lapply(
    demog_schema_list$fields,
    function(field_list) {
      field_list$description &lt;- unname(demog_description_chr[[field_list$name]])
      field_list
    }
  )

  demog_schema_list
}

15.4 Publish the immutable release
Versioned releases are immutable. This target refuses to write into a nonempty version directory, which prevents write_package() from retaining stale CSVs. Changed release content requires a new version directory.
#| format: file
release_kiribati_data_file_published_chr &lt;- {
  release_output_directory_chr &lt;- here::here(
    "data",
    "outputs",
    "releases",
    "v0.1.0"
  )
  release_expected_file_chr &lt;- file.path(
    release_output_directory_chr,
    c("datapackage.json", "biomarker_ptx.csv", "demog_ptx.csv")
  )

  if (
    dir.exists(release_output_directory_chr) &&
      length(
        list.files(
          release_output_directory_chr,
          all.files = TRUE,
          no.. = TRUE
        )
      )
  ) {
    stop(
      "Release directory is nonempty and versioned releases are immutable: ",
      release_output_directory_chr
    )
  }

  dir.create(
    release_output_directory_chr,
    recursive = TRUE,
    showWarnings = FALSE
  )
  frictionless::write_package(
    release_kiribati_data_resource_packaged_list,
    directory = release_output_directory_chr
  )

  release_missing_file_chr &lt;- release_expected_file_chr[
    !file.exists(release_expected_file_chr)
  ]
  if (length(release_missing_file_chr)) {
    stop(
      "Frictionless did not write the expected release files: ",
      paste(release_missing_file_chr, collapse = ", ")
    )
  }

  release_expected_file_chr
}
